-- Model source review, checked 2026-10-19 against Garmin's device list and
-- libmtp (the source versions of migration 084). Data only: no report,
-- assignment, permission or statistic is changed here; identity assessment
-- reads the reviewed links on its next pass.
--
-- 1. A newer source snapshot of a link that already exists added a second
--    row (the unique key includes source_version), mostly retail SKU links
--    re-added by each changed product page. Undecided duplicates without review history are removed;
--    the decided or oldest row of each link stays.
DELETE FROM device_identity_mapping d
WHERE d.status = 'PENDING'
  AND NOT EXISTS (SELECT 1 FROM device_identity_mapping_audit a WHERE a.mapping_id = d.id)
  AND EXISTS (
      SELECT 1 FROM device_identity_mapping o
      WHERE o.id <> d.id AND o.kind = d.kind AND o.value = d.value
        AND o.device_model_id = d.device_model_id
        AND (o.status <> 'PENDING' OR o.id < d.id));

-- 2. Links and decisions. PENDING and APPROVED rows are every link the
--    corrected import (identity_registry.prepare_mappings with variant checks)
--    makes from these source versions, so no import run is needed. APPROVED
--    rows are the catalog models the source itself names for the code;
--    REJECTED rows are earlier import links whose source names a different
--    variant (the import dropped those words). Only undecided links change;
--    an administrator's decision always stays.
CREATE TEMP TABLE identity_source_review_seed (facts jsonb) ON COMMIT DROP;

-- Missing links are added first, then reviewed like existing ones.
SELECT s.facts->>'kind', s.facts->>'value', d.id, s.facts->>'source_url', s.facts->>'source_version', s.facts->'source_names'
FROM identity_source_review_seed s
JOIN device_model d ON d.id = s.facts->>'device_model_id'
WHERE s.facts->>'decision' IN ('APPROVED', 'PENDING')
  AND NOT EXISTS (
      SELECT 1 FROM device_identity_mapping m
      WHERE m.kind = s.facts->>'kind' AND m.value = s.facts->>'value' AND m.device_model_id = d.id);

WITH reviewed AS (
    UPDATE device_identity_mapping m
    SET status = s.facts->>'decision', review_reason = s.facts->>'reason', reviewed_by = NULL, reviewed_at = now()
    FROM identity_source_review_seed s
    WHERE m.status = 'PENDING' AND s.facts->>'decision' <> 'PENDING'
      AND m.kind = s.facts->>'kind' AND m.value = s.facts->>'value'
      AND m.device_model_id = s.facts->>'device_model_id'
    RETURNING m.id, m.status, m.review_reason)
SELECT id, 'PENDING', status, review_reason FROM reviewed;
